import { useState } from "react";
import { useResults } from "../context/ResultsContext";
import { useNavigate } from "react-router-dom";
import { exportResults } from "../api";

export default function Results() {
  const { results } = useResults();
  const navigate = useNavigate();
  const [filter, setFilter] = useState("All");

  const filtered =
    filter === "All" ? results : results.filter((r) => r.decision === filter);

  return (
    <div className="page-wrapper">
      <div className="container-fluid px-5">
        <h2>Results</h2>

        <button
          className="theme-btn mb-3"
          onClick={async () => {
            const blob = await exportResults();
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = "results.csv";
            a.click();
          }}
        >
          Download CSV
        </button>

        {filtered.map((r, i) => (
          <div
            key={i}
            className="theme-card mb-3"
            onClick={() => navigate(`/candidate/${i}`)}
          >
            <strong>{r.filename}</strong>
            <div>
              {r.decision} • {r.final_score}%
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
